if(in_array($type,['IN','OUT'])) $transactions=array_values(array_filter($transactions,fn($t)=>$t['type']===$type)); usort($transactions,fn($a,$b)=>strcmp($b['created_at'],$a['created_at'])); include 'header.php'; ?>
