<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>SKU</th><th>Barang</th><th>Tipe</th><th>Jumlah</th><th>Catatan</th><th>Aksi</th></tr></thead><tbody><?php if(!$transactions): ?><tr><td colspan="7" class="text-muted">Belum ada transaksi.</td></tr><?php endif; foreach($transactions as $t): $item=find_item($t['item_id']); ?><tr><td><?= date('d/m/Y H:i',strtotime($t['created_at'])) ?></td><td><span class="sku-tag"><?= e($item['sku']??'-') ?></span></td><td><?= e($item['name']??'Barang telah dihapus') ?></td><td><span class="badge <?= $t['type']==='IN'?'in':'out' ?>"><?= $t['type']==='IN'?'Masuk':'Keluar' ?></span></td><td><strong><?= number_format($t['quantity']) ?></strong> <?= e($item['unit']??'') ?></td><td><?= e($t['note']??'-') ?></td><td><a href="stock_tx_delete.php?id=<?= $t['id'] ?>" class="btn btn-danger btn-sm" onclick="return confirm('Hapus riwayat ini dan sesuaikan stok?')">Hapus</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php include 'footer.php'; ?>